import Chart from 'assets/bar-chart.svg';
import Table from 'assets/table.svg';

export const SEGMENTED_CONTROL_OPTIONS = [
  { value: 'chart', imageSrc: Chart, imageAlt: 'Chart' },
  { value: 'table', imageSrc: Table, imageAlt: 'Table' },
];
